"""Командная строка для локальной демонстрации очереди.

    python -m jobq.cli demo --jobs 5 --fail-every 3
    python -m jobq.cli types
"""

from __future__ import annotations

import argparse
import logging
import sys
from collections.abc import Sequence

from .clock import ManualClock
from .dashboard import render_report
from .models import Job
from .queue import JobQueue
from .registry import HandlerRegistry
from .worker import Worker

logger = logging.getLogger(__name__)


def build_demo_registry(fail_every: int) -> HandlerRegistry:
    registry = HandlerRegistry()

    @registry.handler("echo")
    def echo(job: Job) -> object:
        return job.payload.get("message")

    @registry.handler("flaky")
    def flaky(job: Job) -> object:
        number = int(job.payload.get("n", 0))
        if fail_every and number % fail_every == 0:
            raise RuntimeError(f"flaky job #{number} failed")
        return number

    return registry


def cmd_demo(args: argparse.Namespace) -> int:
    clock = ManualClock()
    queue = JobQueue(clock=clock)
    worker = Worker(queue, build_demo_registry(args.fail_every), name="demo")

    for number in range(1, args.jobs + 1):
        queue.enqueue("flaky", {"n": number}, delay=float(number))
    queue.enqueue("echo", {"message": "hello"})

    for _ in range(args.jobs + 1):
        worker.run_pending()
        clock.advance(1.0)

    print(render_report(queue))
    return 0


def cmd_types(args: argparse.Namespace) -> int:
    for job_type in build_demo_registry(args.fail_every).job_types():
        print(job_type)
    return 0


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="jobq", description="jobq demo utility")
    parser.add_argument("-v", "--verbose", action="store_true", help="debug logging")
    parser.add_argument("--fail-every", type=int, default=3, help="make every N-th flaky job fail")
    sub = parser.add_subparsers(dest="command", required=True)

    demo = sub.add_parser("demo", help="run a small simulated workload")
    demo.add_argument("--jobs", type=int, default=5)
    demo.set_defaults(func=cmd_demo)

    types = sub.add_parser("types", help="list demo job types")
    types.set_defaults(func=cmd_types)
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    logging.basicConfig(level=logging.DEBUG if args.verbose else logging.WARNING)
    return args.func(args)


if __name__ == "__main__":
    sys.exit(main())
"""Источники времени.

Код пакета никогда не вызывает ``datetime.now()`` напрямую: время всегда берётся
из объекта-часов, который внедряется в :class:`~jobq.queue.JobQueue`.
Все моменты времени — aware ``datetime`` в UTC.
"""

from __future__ import annotations

from datetime import datetime, timedelta, timezone
from typing import Protocol

from .errors import ConfigError

DEFAULT_START = datetime(2024, 1, 1, tzinfo=timezone.utc)


class Clock(Protocol):
    """Минимальный интерфейс часов."""

    def now(self) -> datetime: ...


class SystemClock:
    """Реальные часы (UTC)."""

    def now(self) -> datetime:
        return datetime.now(timezone.utc)


class ManualClock:
    """Часы, которые двигаются только вручную. Используются в тестах и демо."""

    def __init__(self, start: datetime | None = None) -> None:
        moment = DEFAULT_START if start is None else start
        _require_aware(moment)
        self._now = moment

    def now(self) -> datetime:
        return self._now

    def advance(self, seconds: float = 0.0) -> datetime:
        """Сдвинуть часы вперёд на ``seconds`` секунд и вернуть новое время."""
        if seconds < 0:
            raise ConfigError("ManualClock cannot move backwards")
        self._now = self._now + timedelta(seconds=seconds)
        return self._now

    def set(self, moment: datetime) -> None:
        """Установить конкретный момент (не раньше текущего)."""
        _require_aware(moment)
        if moment < self._now:
            raise ConfigError("ManualClock cannot move backwards")
        self._now = moment


def _require_aware(moment: datetime) -> None:
    if moment.tzinfo is None or moment.utcoffset() is None:
        raise ConfigError("clock requires timezone-aware datetimes")
"""Реестр обработчиков по типу задания."""

from __future__ import annotations

import logging
from collections.abc import Callable
from typing import Any

from .errors import ConfigError, DuplicateHandlerError, UnknownJobTypeError
from .models import Job

logger = logging.getLogger(__name__)

Handler = Callable[[Job], Any]


class HandlerRegistry:
    """Сопоставляет тип задания (строку) с функцией-обработчиком ``handler(job) -> result``."""

    def __init__(self) -> None:
        self._handlers: dict[str, Handler] = {}

    def register(self, job_type: str, handler: Handler, *, replace: bool = False) -> None:
        if not job_type:
            raise ConfigError("job_type must be a non-empty string")
        if not callable(handler):
            raise ConfigError(f"handler for {job_type!r} is not callable")
        if job_type in self._handlers and not replace:
            raise DuplicateHandlerError(f"handler for {job_type!r} already registered")
        self._handlers[job_type] = handler
        logger.debug("registered handler for %s", job_type)

    def handler(self, job_type: str, *, replace: bool = False) -> Callable[[Handler], Handler]:
        """Декоратор-обёртка над :meth:`register`."""

        def decorator(func: Handler) -> Handler:
            self.register(job_type, func, replace=replace)
            return func

        return decorator

    def get(self, job_type: str) -> Handler:
        try:
            return self._handlers[job_type]
        except KeyError:
            raise UnknownJobTypeError(job_type) from None

    def __contains__(self, job_type: object) -> bool:
        return job_type in self._handlers

    def job_types(self) -> list[str]:
        return sorted(self._handlers)

